  'landing.faq.1.q': 'How fast are orders delivered?',
  'landing.faq.1.a': 'Most services start within 0–30 minutes and complete progressively. Speed per service is shown in the catalogue (e.g. 5k/day), and the platform tracks start count and remains on every order automatically.',
  'landing.faq.2.q': 'Which payment methods are supported?',
  'landing.faq.2.a': 'You can accept credit cards, PayPal, crypto (USDT, BTC and more) and manual methods. Every gateway supports custom fees, and deposits are credited to client wallets instantly or after approval — you choose the mode.',
  'landing.faq.3.q': 'Can I offer refunds?',
  'landing.faq.3.a': 'Yes. Canceled and partial orders can be refunded straight back to the client wallet with one click, and every movement is recorded in the double-entry ledger for both you and your customers.',
  'landing.faq.4.q': 'Is there an API for my customers and resellers?',
  'landing.faq.4.a': 'Absolutely — a standard SMM API v2 (services, add, status, balance) ships with every panel. Resellers plug their own panels or external connectors straight into it, so nothing about your workflow changes.',
  'landing.faq.5.q': 'Can I resell panels to my own customers?',
  'landing.faq.5.a': 'Yes. On any plan you can create white-label reseller panels with their own branding, catalogue, prices and portal. Resellers pay you a monthly membership and you keep 100% of the margin on their orders.',
  'landing.faq.6.q': 'Do services include refill guarantees?',
  'landing.faq.6.a': 'Services marked with refill include an automatic refill window — clients can trigger refills themselves from their portal within the allowed period, and you control cancel/refill permissions per service.',
