  'landing.plan.agency.f6': 'SLA de disponibilidad del 99.9%',
  'landing.step.1.title': 'Elige tu plan',
  'landing.step.1.desc': 'Empieza en Starter, Pro o Agency — mejora de plan cuando tu volumen crezca.',
  'landing.step.2.title': 'Elige tu dominio',
  'landing.step.2.desc': 'Obtén un subdominio gratis al instante, o conecta tu propio dominio.',
  'landing.step.3.title': 'Lanza y revende',
  'landing.step.3.desc': 'Importa servicios, pone tus precios y empieza a recibir pedidos hoy mismo.',
  'landing.faq.1.q': '¿Qué tan rápido se entregan los pedidos?',
  'landing.faq.1.a': 'La mayoría de los servicios arrancan entre 0 y 30 minutos y avanzan de forma progresiva. La velocidad de cada servicio se muestra en el catálogo (p. ej. 5k/día), y la plataforma registra el start count y el remain automáticamente en cada pedido.',
  'landing.faq.2.q': '¿Qué métodos de pago hay disponibles?',
  'landing.faq.2.a': 'Puedes aceptar tarjetas de crédito, PayPal, cripto (USDT, BTC y más) y métodos manuales. Cada pasarela admite comisiones personalizadas, y los depósitos se acreditan en el wallet del cliente al instante o tras aprobación — tú eliges el modo.',
  'landing.faq.3.q': '¿Puedo ofrecer reembolsos?',
  'landing.faq.3.a': 'Sí. Los pedidos cancelados y parciales se pueden reembolsar directamente al wallet del cliente con un clic, y cada movimiento queda registrado en el libro de doble entrada tanto para ti como para tus clientes.',
  'landing.faq.4.q': '¿Hay una API para mis clientes y revendedores?',
  'landing.faq.4.a': 'Claro — cada panel incluye una API SMM v2 estándar (services, add, status, balance). Los revendedores conectan sus propios paneles o conectores externos directamente a ella, así que tu flujo de trabajo no cambia en nada.',
  'landing.faq.5.q': '¿Puedo revender paneles a mis propios clientes?',
  'landing.faq.5.a': 'Sí. Con cualquier plan puedes crear paneles de reventa white-label con su propia marca, catálogo, precios y portal. Los revendedores te pagan una membresía mensual y tú te quedas con el 100% del margen de sus pedidos.',
  'landing.faq.6.q': '¿Los servicios incluyen garantía de refill?',
  'landing.faq.6.a': 'Los servicios marcados con refill incluyen una ventana automática de reposición — tus clientes pueden pedir refills desde su portal dentro del período permitido, y tú controlas los permisos de cancelación/refill por servicio.',
  'landing.networksTitle': 'De Instagram a Spotify — un catálogo para todas las plataformas.',
  'landing.faqTitle': 'Preguntas, respondidas.',
